function parseRoman(s) {
  if (typeof s !== 'string' || s.length === 0) return -1;
  const V = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  for (const ch of s) if (!(ch in V)) return -1;
  if (/(.)\1{3,}/.test(s)) return -1;
  const ok = new Set(['IV', 'IX', 'XL', 'XC', 'CD', 'CM']);
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const cur = V[s[i]], next = i + 1 < s.length ? V[s[i + 1]] : 0;
    if (cur < next) {
      if (!ok.has(s[i] + s[i + 1])) return -1;
      total += next - cur;
      i++;
    } else total += cur;
  }
  return total;
}

