function flattenDepth(arr, d) {
  if (d < 0) return null;
  if (d === 0) return arr.slice();
  const out = [];
  for (const el of arr) {
    if (Array.isArray(el)) out.push(...flattenDepth(el, d - 1));
    else out.push(el);
  }
  return out;
}

