function replaceAllSimultaneous(s, pairs) {
  const ps = (pairs || []).filter((p) => p && typeof p[0] === 'string' && p[0].length > 0);
  let out = '';
  let i = 0;
  outer: while (i < s.length) {
    for (const p of ps) {
      if (s.startsWith(p[0], i)) { out += p[1]; i += p[0].length; continue outer; }
    }
    out += s[i];
    i++;
  }
  return out;
}

