function chunkMinTail(arr, n) {
  if (!(n >= 1)) return null;
  if (arr.length === 0) return [];
  const out = [];
  for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
  const min = Math.ceil(n / 2);
  if (out.length > 1 && out[out.length - 1].length < min) {
    const tail = out.pop();
    out[out.length - 1] = out[out.length - 1].concat(tail);
  }
  return out;
}

