function sortByKeys(rows, keys) {
  const dec = rows.map((row, i) => ({ row: row, i: i }));
  dec.sort((a, b) => {
    for (const k of keys) {
      const prop = k[0], dir = k[1] === 'desc' ? -1 : 1;
      const x = a.row[prop], y = b.row[prop];
      if (x < y) return -1 * dir;
      if (x > y) return 1 * dir;
    }
    return a.i - b.i;
  });
  return dec.map((d) => d.row);
}

